const rawItems = [];

const extractRss = (nodeName, defaultSource) => {
  try {
    const items = $(nodeName).all();
    for (const item of items) {
      const j = item.json || {};
      const title = String(j.title || j['rss:title'] || '').trim();
      const link = String(j.link || j.guid || j['rss:link'] || '').trim();
      const desc = String(j.contentSnippet || j.content || j.description || '').replace(/<[^>]*>?/gm, '').trim();
      const pubDate = String(j.pubDate || j.isoDate || new Date().toISOString());

      if (title && link) {
        rawItems.push({
          title,
          url: link,
          snippet: desc.slice(0, 300),
          source: defaultSource,
          pubDate
        });
      }
    }
  } catch (e) {}
};

// 1. Feeds de Venezuela
extractRss('RSS El Nacional', 'El Nacional (Venezuela)');
extractRss('RSS Tal Cual', 'Tal Cual Digital (Venezuela)');
extractRss('RSS La Verdad', 'La Verdad (Venezuela)');
extractRss('RSS Alertas 24', 'Alertas 24 (Venezuela)');
extractRss('RSS Twitter Venezuela', 'X / Twitter (Venezuela)');

// Scraper HTML El Universal
try {
  const elUniItems = $('HTTP El Universal').all();
  for (const item of elUniItems) {
    const html = String(item.json?.data || '');
    const regex = /<a[^>]+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi;
    let match;
    let count = 0;
    while ((match = regex.exec(html)) !== null && count < 25) {
      const rawHref = match[1];
      const linkText = match[2].replace(/<[^>]*>?/gm, '').trim();
      if (linkText.length > 25 && !linkText.includes('Publicidad') && !linkText.includes('Términos')) {
        let fullUrl = rawHref;
        if (fullUrl.startsWith('/')) {
          fullUrl = 'https://www.eluniversal.com' + fullUrl;
        }
        if (fullUrl.startsWith('http')) {
          rawItems.push({
            title: linkText,
            url: fullUrl,
            snippet: linkText,
            source: 'El Universal (Venezuela)',
            pubDate: new Date().toISOString()
          });
          count++;
        }
      }
    }
  }
} catch (e) {}

// 2. Feeds Internacionales, Deportes y X/Twitter Global
extractRss('RSS El Pais', 'El País Internacional');
extractRss('RSS BBC Mundo', 'BBC Mundo');
extractRss('RSS NYTimes World', 'NYTimes RSS');
extractRss('RSS Twitter Global', 'X / Twitter (Internacional / USA)');

// 3. APIs Externas
try {
  const nytItems = $('API NYTimes TopStories').all();
  for (const item of nytItems) {
    const results = item.json?.results || [];
    for (const r of results) {
      if (r.title && r.url) {
        rawItems.push({
          title: String(r.title).trim(),
          url: String(r.url).trim(),
          snippet: String(r.abstract || '').slice(0, 300),
          source: 'NYTimes API',
          pubDate: String(r.published_date || new Date().toISOString())
        });
      }
    }
  }
} catch (e) {}

try {
  const gnewsItems = $('API GNews TopHeadlines').all();
  for (const item of gnewsItems) {
    const articles = item.json?.articles || [];
    for (const a of articles) {
      if (a.title && a.url) {
        rawItems.push({
          title: String(a.title).trim(),
          url: String(a.url).trim(),
          snippet: String(a.description || '').slice(0, 300),
          source: 'GNews API',
          pubDate: String(a.publishedAt || new Date().toISOString())
        });
      }
    }
  }
} catch (e) {}

try {
  const newsApiItems = $('API NewsAPI Technology').all();
  for (const item of newsApiItems) {
    const articles = item.json?.articles || [];
    for (const a of articles) {
      if (a.title && a.url) {
        rawItems.push({
          title: String(a.title).trim(),
          url: String(a.url).trim(),
          snippet: String(a.description || '').slice(0, 300),
          source: 'NewsAPI Tech',
          pubDate: String(a.publishedAt || new Date().toISOString())
        });
      }
    }
  }
} catch (e) {}

try {
  const wnItems = $('API WorldNews').all();
  for (const item of wnItems) {
    const news = item.json?.news || [];
    for (const n of news) {
      if (n.title && n.url) {
        rawItems.push({
          title: String(n.title).trim(),
          url: String(n.url).trim(),
          snippet: String(n.text || '').slice(0, 300),
          source: 'WorldNews API',
          pubDate: String(n.publish_date || new Date().toISOString())
        });
      }
    }
  }
} catch (e) {}

// 4. Feeds Especializados (Tecnología, Deportes y Entretenimiento)
extractRss('RSS Xataka MX', 'Xataka México (Tecnología)');
extractRss('RSS El Nacional CyT', 'El Nacional CyT (Tecnología)');
extractRss('RSS The Verge', 'The Verge (Tecnología)');
extractRss('RSS Wired', 'Wired (Tecnología)');
extractRss('RSS Lider en Deportes', 'Líder en Deportes (Venezuela/Deportes)');
extractRss('RSS Meridiano', 'Meridiano (Venezuela/Deportes)');
extractRss('RSS El Nacional Deportes', 'El Nacional Deportes (Venezuela/Deportes)');
extractRss('RSS ESPN Deportes', 'ESPN Deportes (Deportes)');
extractRss('RSS El Nacional Entretenimiento', 'El Nacional Entretenimiento (Espectáculo)');
extractRss('RSS Telemundo Entretenimiento', 'Telemundo Entretenimiento (Espectáculo)');
extractRss('RSS CNN Espanol Entretenimiento', 'CNN en Español Entretenimiento (Espectáculo)');
extractRss('RSS Variety', 'Variety (Espectáculo)');
extractRss('RSS Hollywood Reporter', 'The Hollywood Reporter (Espectáculo)');
extractRss('RSS Rolling Stone', 'Rolling Stone (Espectáculo)');
extractRss('RSS El Pais Cultura', 'El País Cultura (Espectáculo)');
extractRss('RSS Telecomunicaciones 360', 'Telecomunicaciones 360 (Tecnología/Telecom)');

// =========================================================================
// GESTIÓN DE HISTORIAL PERSISTENTE DE 72 HORAS (MEMORIA DE EDICIONES PREVIAS)
// =========================================================================
const workflowStatic = $getWorkflowStaticData('global');
const nowMs = Date.now();
const window72hMs = 72 * 60 * 60 * 1000;

if (!Array.isArray(workflowStatic.sentNewsHistory)) {
  workflowStatic.sentNewsHistory = [];
}

// Depurar noticias mayores a 72 horas
workflowStatic.sentNewsHistory = workflowStatic.sentNewsHistory.filter(item => {
  return item && item.ts && (nowMs - item.ts) <= window72hMs;
});

const pastSentItems = workflowStatic.sentNewsHistory;
const pastSentUrls = new Set(pastSentItems.map(p => String(p.url || '').split('?')[0].toLowerCase()).filter(Boolean));
const pastSentTitles = pastSentItems.map(p => String(p.title || '').trim()).filter(Boolean);

// Función de extracción de palabras clave para similitud semántica
const stopWords = new Set([
  'de', 'la', 'el', 'en', 'y', 'a', 'del', 'las', 'los', 'por', 'para', 'un', 'una', 'con', 'que',
  'al', 'su', 'sus', 'se', 'sobre', 'tras', 'entre', 'como', 'mas', 'pero', 'este', 'esta', 'estos',
  'estas', 'le', 'les', 'fue', 'son', 'era', 'dos', 'tres', 'ante', 'desde', 'hasta', 'hacia', 'sin'
]);

const getKeywords = (text) => {
  const words = (text || '').toLowerCase().match(/[a-záéíóúñ]{4,}/g) || [];
  return new Set(words.filter(w => !stopWords.has(w)));
};

const pastTitleKeywordSets = pastSentTitles.map(t => ({
  title: t,
  keywords: getKeywords(t)
}));

// Desduplicación por URL, título exacto y filtro contra emisiones previas (72h)
const seenUrls = new Set();
const seenTitles = new Set();
const uniqueArticles = [];
let countFilteredByHistory = 0;

const normalizeTitle = (t) => t.toLowerCase().replace(/[^a-z0-9áéíóúñ]/g, '');

for (const art of rawItems) {
  const normUrl = art.url.split('?')[0].toLowerCase();
  const normT = normalizeTitle(art.title);

  // Duplicado en la misma emisión
  if (seenUrls.has(normUrl) || seenTitles.has(normT)) {
    continue;
  }

  // 1. Filtrar si la URL exacta ya fue publicada en las últimas 72 horas
  if (pastSentUrls.has(normUrl)) {
    countFilteredByHistory++;
    continue;
  }

  // 2. Filtrar si coincide temáticamente con una noticia ya publicada en las últimas 72h
  const candKeywords = getKeywords(art.title);
  let isDupeWithPast = false;

  if (candKeywords.size >= 2) {
    for (const pastObj of pastTitleKeywordSets) {
      if (pastObj.keywords.size < 2) continue;

      let common = 0;
      for (const kw of candKeywords) {
        if (pastObj.keywords.has(kw)) common++;
      }

      const minLen = Math.min(candKeywords.size, pastObj.keywords.size);
      // Coincidencia estricta: 3 palabras clave idénticas o >= 50% de superposición
      if (common >= 3 || (common >= 2 && (common / minLen) >= 0.5)) {
        isDupeWithPast = true;
        break;
      }
    }
  }

  if (isDupeWithPast) {
    countFilteredByHistory++;
    continue;
  }

  seenUrls.add(normUrl);
  seenTitles.add(normT);
  uniqueArticles.push(art);
}

// Balanceo Garantizado: Extraer artículos de Venezuela, USA, Tech, Deportes, Espectáculo y Global
const veSources = [
  'El Nacional (Venezuela)',
  'Tal Cual Digital (Venezuela)',
  'La Verdad (Venezuela)',
  'El Universal (Venezuela)',
  'Alertas 24 (Venezuela)',
  'X / Twitter (Venezuela)',
  'Líder en Deportes (Venezuela/Deportes)',
  'Meridiano (Venezuela/Deportes)',
  'El Nacional Deportes (Venezuela/Deportes)'
];

const usSources = [
  'NYTimes RSS',
  'NYTimes API',
  'GNews API',
  'NewsAPI Tech',
  'X / Twitter (Internacional / USA)',
  'The Verge (Tecnología)',
  'Wired (Tecnología)',
  'Variety (Espectáculo)',
  'The Hollywood Reporter (Espectáculo)',
  'Rolling Stone (Espectáculo)'
];

const veList = [];
const usList = [];
const otherList = [];

for (const art of uniqueArticles) {
  if (veSources.includes(art.source)) {
    veList.push(art);
  } else if (usSources.includes(art.source)) {
    usList.push(art);
  } else {
    otherList.push(art);
  }
}

// Combinar garantizando diversidad de fuentes
const balancedArticles = [
  ...veList.slice(0, 40),
  ...usList.slice(0, 35),
  ...otherList.slice(0, 45)
];

let originChatId = null;
try {
  const tgData = $('Telegram Command Trigger').first()?.json || {};
  if (tgData.message && tgData.message.chat) {
    originChatId = String(tgData.message.chat.id);
  }
} catch (e) {}

return [{
  json: {
    total_raw: rawItems.length,
    total_unique: uniqueArticles.length,
    total_filtered_history_72h: countFilteredByHistory,
    total_in_history: pastSentTitles.length,
    past_titles_72h: pastSentTitles.slice(-30),
    total_ve: veList.length,
    total_us: usList.length,
    origin_chat_id: originChatId,
    articles: balancedArticles
  }
}];

const rawText = $json.choices[0].message.content.trim();
const normData = $('Normalizar y Desduplicar Noticias').first()?.json || {};

// =========================================================================
// REGISTRAR NOTICIAS DE ESTA EMISIÓN EN EL HISTORIAL DE 72 HORAS
// =========================================================================
try {
  const workflowStatic = $getWorkflowStaticData('global');
  if (!Array.isArray(workflowStatic.sentNewsHistory)) {
    workflowStatic.sentNewsHistory = [];
  }

  // Extraer titulares y enlaces mediante expresiones regulares
  const pattern = /\*\*([^\*\n]+)\*\*[\s\S]*?\[Leer noticia[^\]]*\]\((https?:\/\/[^\)]+)\)/gi;
  let match;
  const nowTs = Date.now();
  let countSaved = 0;

  while ((match = pattern.exec(rawText)) !== null) {
    const title = match[1].replace(/^\d+[\.\)]\s*/, '').trim();
    const url = match[2].trim();
    if (title) {
      workflowStatic.sentNewsHistory.push({
        title,
        url,
        ts: nowTs
      });
      countSaved++;
    }
  }

  // Mantener solo los últimos 72 horas y máximo 300 registros
  const window72hMs = 72 * 60 * 60 * 1000;
  workflowStatic.sentNewsHistory = workflowStatic.sentNewsHistory
    .filter(item => item && item.ts && (nowTs - item.ts) <= window72hMs)
    .slice(-300);
} catch (e) {}

const dateStr = new Date().toLocaleDateString('es-ES', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
const header = `📰 *RESUMEN DE NOTICIAS DESTACADAS* 🗞️\n📅 *${dateStr.toUpperCase()}*\n----------------------------------------\n\n`;

const fullText = header + rawText;

function chunkMessage(text, maxLen = 3500) {
  if (text.length <= maxLen) return [text];
  const result = [];
  let rem = text;
  while (rem.length > maxLen) {
    let idx = rem.lastIndexOf('\n\n', maxLen);
    if (idx === -1 || idx < maxLen / 2) {
      idx = rem.lastIndexOf('\n', maxLen);
    }
    if (idx === -1 || idx < maxLen / 2) {
      idx = maxLen;
    }
    result.push(rem.slice(0, idx).trim());
    rem = rem.slice(idx).trim();
  }
  if (rem) result.push(rem);
  return result;
}

const chunks = chunkMessage(fullText, 3500);

return chunks.map((c, i) => ({
  json: {
    part: i + 1,
    total_parts: chunks.length,
    telegram_text: chunks.length > 1 ? `*(Parte ${i + 1}/${chunks.length})*\n\n${c}` : c,
    origin_chat_id: normData.origin_chat_id || null
  }
}));

// Determinar la hora de envío programada (9am, 12pm, 7pm) o la hora actual
const now = new Date();
const hour = parseInt(new Intl.DateTimeFormat('en-US', {
  hour: 'numeric',
  hour12: false,
  timeZone: 'America/Caracas'
}).format(now), 10);

let horaEnvio = '9am';
if (hour >= 8 && hour <= 10) {
  horaEnvio = '9am';
} else if (hour >= 11 && hour <= 14) {
  horaEnvio = '12pm';
} else if (hour >= 18 && hour <= 21) {
  horaEnvio = '7pm';
} else {
  const hour12 = hour % 12 || 12;
  const ampm = hour < 12 ? 'am' : 'pm';
  horaEnvio = `${hour12}${ampm}`;
}

return [{
  json: {
    whatsapp_text: `Noticias ${horaEnvio} enviadas`
  }
}];
